# -*- coding: utf-8 -*-
from pathlib import Path

ROOT = Path(__file__).resolve().parent

def head(slug, title):
    return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Unfold 디자인 시안</title><meta name="description" content="원하는 펫과 3D(GLB) 펫을 넣어 사용하는 Unfold의 새로운 판매 웹 디자인 시안."><link rel="icon" href="./assets/app-icon.png"><link rel="stylesheet" href="./base.css"><link rel="stylesheet" href="./{slug}.css"></head><body class="{slug}" id="top"><a class="skip" href="#main">본문으로 건너뛰기</a>'''

def nav():
    return '''<header class="header"><nav class="site-nav wrap" aria-label="주요 메뉴"><a class="brand" href="#top" aria-label="Unfold 처음으로"><img src="./assets/logo-lilac.svg" width="1162" height="320" alt="Unfold"></a><button class="menu-toggle" aria-label="메뉴 열기" aria-expanded="false" aria-controls="nav-links" type="button">☰</button><div class="nav-links" id="nav-links"><a href="#features">나만의 펫</a><a href="#showcase">앱 화면</a><a class="nav-buy" href="#purchase">구매 안내</a></div></nav></header>'''

def actions(primary='내 펫과 시작하기', secondary='앱 화면 보기'):
    return f'''<div class="actions"><a class="btn" href="#purchase">{primary}<span class="arrow" aria-hidden="true">↗</span></a><a class="btn secondary" href="#showcase">{secondary}</a></div>'''

def pet(inline=False):
    if inline:
        return '<span class="inline-pet" aria-hidden="true"><img src="./assets/pet-rest.png" alt=""></span>'
    return '<img class="pet-art" src="./assets/pet-stretch.webp" alt="휴식을 함께하는 고양이 Mochi" width="256" height="256">'

def carousel(theme):
    return f'''<div class="screen-carousel" data-carousel data-theme="{theme}" data-current="0"><figure class="frame screen-frame"><img src="./assets/{theme}-home.png" alt="Unfold 타이머 실제 앱 화면" width="1120" height="800" data-screen data-scale></figure><div class="carousel-meta"><p aria-live="polite"><span class="carousel-name" data-screen-name>타이머</span><span class="carousel-count" data-screen-count>1 / 3</span></p><div class="carousel-controls"><button class="icon-button" data-prev aria-label="이전 앱 화면" type="button">←</button><button class="icon-button" data-next aria-label="다음 앱 화면" type="button">→</button></div></div><p class="caption">실제 앱 화면 · Beta v1.1.3 개발본</p></div>'''

def accordion(theme, identifier):
    labels = [('내가 고른 펫', 'pet-rest.png', '고양이 Mochi'), ('쉬어 갈 시간', f'{theme}-speech.png', '현재 앱의 휴식 알림'), ('내 휴식 기록', f'{theme}-review.png', '현재 앱의 휴식 기록')]
    parts=[]
    for i,(label,asset,alt) in enumerate(labels):
        parts.append(f'''<article class="accordion-item {'is-active' if i == 0 else ''}"><h3><button class="accordion-trigger" type="button" aria-expanded="{'true' if i == 0 else 'false'}" aria-controls="{identifier}-{i}"><span>{label}</span><span aria-hidden="true">↗</span></button></h3><div class="accordion-panel" id="{identifier}-{i}"><img src="./assets/{asset}" alt="{alt}" width="{'256' if i == 0 else '524' if i == 1 else '1120'}" height="{'256' if i == 0 else '196' if i == 1 else '800'}"></div></article>''')
    return '<div class="accordion">'+''.join(parts)+'</div>'

def price(title):
    return f'''<section class="purchase section" id="purchase"><div class="wrap purchase-layout"><div class="purchase-copy"><p class="kicker">Unfold for your desktop</p><h2>{title}</h2><p class="desktop-note">Windows 10 이상 · macOS 13 이상</p></div><div class="purchase-action"><p class="price-label">테스트 기준가 · 세금 별도</p><p class="price-number">4,900<span>원</span></p><button class="btn" type="button" data-purchase>구매 안내 보기<span class="arrow" aria-hidden="true">↗</span></button><p class="purchase-note">정식 판매 전이며 실제 청구되지 않습니다.<br>Beta는 이용 코드를 받은 테스터가 사용할 수 있습니다.</p></div></div></section>'''

def end():
    return '''</main><footer class="wrap foot"><a href="./index.html" class="comparison-back">네 가지 시안 비교</a><p>© 2026 Unfold · 디자인 시안</p><p>원하는 펫을 내 데스크톱에.</p></footer><dialog class="purchase-dialog" aria-labelledby="purchase-title"><button type="button" class="dialog-close" aria-label="구매 안내 닫기">×</button><h2 id="purchase-title">Beta 이용 안내</h2><p>현재 공개 버전은 Beta v1.1.2입니다. 앱에서 Google 계정으로 로그인하고 발급받은 이용 코드를 등록해 사용합니다.</p><p>4,900원은 세금 별도 테스트 기준가입니다. 웹 테스트 결제는 실제 청구되지 않으며 앱 이용 권한을 제공하지 않습니다.</p><a class="btn" href="https://unfoldpet.dokhustudio.com/#install" target="_blank" rel="noopener">공식 Beta 다운로드 <span aria-hidden="true">↗</span></a><p class="purchase-note">판매 웹 디자인 시안으로, 이 페이지에서 결제를 진행하지 않습니다.</p></dialog><script type="module" src="./concepts.js"></script></body></html>'''

studio = head('studio','Quiet studio')+nav()+f'''<main id="main"><section class="hero studio-hero"><div class="wrap"><div class="hero-copy"><p class="kicker">A little friend for your desktop</p><h1 class="max-w-6xl">A little pause.<br>A pet of your own.</h1><div class="hero-bottom"><div><p class="hero-korean">내가 고른 펫과,<br>잠깐 쉬어가세요.</p><p class="lead">이미지·영상부터 3D(GLB)까지.</p>{actions()}</div></div></div><div class="pet-stage"><div class="stage-shadow"></div>{pet()}<span class="stage-line" aria-hidden="true"></span></div></div></section><div class="marquee" aria-label="지원하는 펫 형식"><div class="marquee-track"><span>YOUR PET. YOUR DESKTOP. &nbsp; IMAGE · GIF · MP4 · 3D(GLB) &nbsp;</span><span aria-hidden="true">YOUR PET. YOUR DESKTOP. &nbsp; IMAGE · GIF · MP4 · 3D(GLB) &nbsp;</span></div></div><section class="section studio-features" id="features"><div class="wrap"><p class="kicker">Your own little companion</p><h2 class="section-heading">좋아하는 펫을 {pet(True)}<br>내 화면 곁에.</h2><div class="dense-grid studio-grid"><article class="file-card"><h3>이미지·GIF·MP4</h3><div class="file-composition" aria-hidden="true"><span class="file-sheet">image<br><strong>.png</strong></span><span class="file-sheet">motion<br><strong>.gif</strong></span><span class="file-sheet">video<br><strong>.mp4</strong></span></div></article><article class="glb-card"><h3>3D(GLB) 펫도 함께.</h3><div class="wire-cube" aria-hidden="true"><span></span></div><p class="formats">.glb</p></article><article class="rest-card"><h3>펫이 알려 주는<br>쉬어 갈 시간.</h3><img src="./assets/oat-speech.png" width="524" height="196" alt="실제 앱의 휴식 알림"></article></div></div></section><section class="section studio-showcase" id="showcase"><div class="wrap showcase-split"><div class="showcase-copy" data-pin><p class="kicker">Small breaks, on your terms</p><h2 class="section-heading">내 하루의<br>쉬어 간 순간.</h2><p class="caption">타이머 · 휴식 기록 · 휴식 알림</p></div><div class="showcase-media">{carousel('oat')}<figure class="studio-record frame"><img src="./assets/oat-review.png" width="1120" height="800" alt="실제 앱의 휴식 기록" data-scale></figure><p class="caption">휴식 기록 · 실제 앱 화면</p></div></div></section>{price('작은 동료를<br>데려올 시간.')}'''+end()

night = head('night','After hours')+nav()+f'''<main id="main"><section class="hero night-hero"><div class="night-glow" aria-hidden="true"></div><div class="wrap night-hero-grid"><div class="hero-copy"><p class="kicker">A companion, even after hours</p><h1 class="max-w-6xl">집중한 하루에,<br>작은 쉼표 하나.</h1><p class="lead">이미지·영상·3D(GLB).<br>원하는 펫을 화면 곁에 두세요.</p>{actions('내 펫과 시작하기','Unfold 살펴보기')}<p class="night-system">Windows · macOS</p></div><div class="night-stage"><div class="orbital orbital-one" aria-hidden="true"></div><div class="orbital orbital-two" aria-hidden="true"></div><div class="night-pet-platform">{pet()}</div><div class="night-speech"><span class="signal" aria-hidden="true"></span><span>잠깐, 쉬어 갈까요?</span></div><div class="night-word" aria-hidden="true">unfold</div></div></div></section><section class="section night-features" id="features"><div class="wrap"><div class="night-section-head"><p class="kicker">Made for your own companion</p><h2 class="section-heading">Your desktop.<br>Your {pet(True)} little friend.</h2><p class="formats">이미지·GIF·MP4 · 3D(GLB)</p></div>{accordion('midnight','night-panel')}</div></section><section class="section night-showcase" id="showcase"><div class="wrap"><div class="night-showcase-heading"><p class="kicker">A closer look</p><h2 class="section-heading">밤에도, 낮에도.<br>내 리듬으로.</h2></div><div class="night-stack"><div class="night-media-card" data-stack>{carousel('midnight')}</div><figure class="night-media-card night-reminder" data-stack><img src="./assets/midnight-speech.png" alt="실제 앱의 휴식 시작 또는 5분 뒤에 알림" width="524" height="196" data-scale><figcaption class="caption">휴식 알림 · Beta v1.1.3 개발본</figcaption></figure></div></div></section>{price('내 화면에,<br>작은 동료 하나.')}'''+end()

club = head('club','Play club')+nav()+f'''<main id="main"><section class="hero club-hero"><div class="wrap"><p class="kicker">Your desktop could use a friend.</p><h1 class="max-w-6xl">Small friend.<br>Big pause.</h1><div class="club-pet-stage"><div class="club-disc" aria-hidden="true"></div>{pet()}<p class="club-side-note">내가 고른 펫과<br>쉬어 가는 시간.</p><p class="club-format-note">이미지 · 영상<br>3D(GLB)</p></div><div class="club-hero-action"><p class="lead">좋아하는 펫을 내 데스크톱에.</p>{actions('내 펫 데려오기','앱 화면 보기')}</div></div></section><section class="section club-features" id="features"><div class="wrap"><div class="club-feature-title"><h2 class="section-heading">A friend<br>in every {pet(True)} form.</h2><p class="formats">이미지·GIF·MP4<br>그리고 3D(GLB).</p></div>{accordion('plum','club-panel')}</div></section><section class="section club-showcase" id="showcase"><div class="wrap club-showcase-grid"><div class="club-showcase-title" data-pin><p class="kicker">Take a look around</p><h2 class="section-heading">작은 쉼을,<br>내 방식으로.</h2></div><div class="club-stack"><div class="club-media-card" data-stack>{carousel('plum')}</div><article class="club-media-card club-record" data-stack><h3>쉬어 간 순간을<br>다시 살펴봐요.</h3><figure class="frame"><img src="./assets/plum-review.png" alt="실제 앱의 휴식 기록과 CSV 내보내기" width="1120" height="800"></figure><p class="caption">휴식 기록 · Beta v1.1.3 개발본</p></article></div></div></section>{price('Your next pause?<br>With Unfold.')}'''+end()

daylight = head('daylight','Daylight')+nav()+f'''<main id="main"><section class="hero daylight-hero"><div class="daylight-sun" aria-hidden="true"></div><div class="cloud cloud-one" aria-hidden="true"></div><div class="cloud cloud-two" aria-hidden="true"></div><div class="wrap daylight-hero-inner"><p class="kicker">A little room to breathe</p><h1 class="max-w-6xl">좋아하는 {pet(True)} 펫과,<br>조금 더 가벼운 하루.</h1><p class="lead">이미지·영상부터 3D(GLB)까지, 원하는 펫과 함께.</p>{actions('내 펫과 시작하기','Unfold 둘러보기')}<div class="daylight-stage"><div class="daylight-horizon" aria-hidden="true"></div><div class="daylight-pet">{pet()}</div></div></div></section><section class="section daylight-features" id="features"><div class="wrap"><h2 class="section-heading reveal-line" data-scrub>내가 고른 펫이 쉬어 갈 시간을 알려줘요.</h2><div class="daylight-feature-row"><p class="formats">이미지·GIF·MP4<br>3D(GLB)</p><span class="daylight-divider" aria-hidden="true"></span><p class="daylight-note">원하는 펫을<br>내 화면 곁에.</p></div>{accordion('sage','daylight-panel')}</div></section><section class="section daylight-showcase" id="showcase"><div class="wrap"><div class="daylight-showcase-title"><p class="kicker">A moment, just for you</p><h2 class="section-heading">내 하루에 어울리는<br>작은 쉼.</h2></div><div class="daylight-screen-stage">{carousel('sage')}</div></div></section>{price('다음 휴식은,<br>좋아하는 펫과.')}'''+end()

for slug,content in [('studio',studio),('night',night),('club',club),('daylight',daylight)]:
    (ROOT/f'{slug}.html').write_text(content,encoding='utf-8')
print('Built four independent concept pages')
